namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new PaymentGateway();
    }

    // ── ChargeAsync ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCharge_ReturnsNonEmptyChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 100m);

        Assert.IsNotNull(result.ChargeId);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ReturnsFalse()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 0m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ReturnsFalse()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", -10m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentNullException()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 10m));

        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(string.Empty, 10m));
    }

    [TestMethod]
    [DataRow("tok_card_declined")]
    [DataRow("tok_expired")]
    [DataRow("tok_insufficient_funds")]
    public async Task ChargeAsync_InvalidToken_ReturnsFalse(string badToken)
    {
        var result = await _gateway.ChargeAsync(badToken, 25m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum charge")]
    [DataRow(9999.99, DisplayName = "Large charge")]
    public async Task ChargeAsync_BoundaryAmounts_ReturnsSuccess(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_TwoCharges_ReturnDifferentChargeIds()
    {
        var first = await _gateway.ChargeAsync("tok_valid_visa", 10m);
        var second = await _gateway.ChargeAsync("tok_valid_visa", 20m);

        Assert.AreNotEqual(first.ChargeId, second.ChargeId);
    }

    // ── RefundAsync ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccess()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 50m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidRefund_ReturnsNonEmptyRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 50m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.AreNotEqual(string.Empty, refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));

        Assert.AreEqual("chargeId", ex.ParamName);
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFalse()
    {
        var refund = await _gateway.RefundAsync("chg_does_not_exist");

        Assert.IsFalse(refund.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFalse()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 75m);
        await _gateway.RefundAsync(charge.ChargeId);

        var duplicate = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsFalse(duplicate.Success);
    }
}

